def render_twitch_piece_overlay(board, orientation):
    """Render the approved Twitch set on a strict one-sprite-per-square grid.

    Every embedded PNG is a complete transparent 1x1-square canvas.  No per-piece
    scaling, baselines, or offsets are applied here; the visual proportions are
    already baked into the approved artwork.  This keeps every piece centered on
    its own chess square and prevents overlap into neighbouring squares.
    """
    square_size = 45.0
    board_offset = 15.0

    present = {piece.symbol() for piece in board.piece_map().values()}
    defs = ['<defs>']
    for symbol in sorted(present):
        payload = TWITCH_PIECE_PNG_BASE64.get(symbol)
        if not payload:
            continue
        safe = f"tw_{ord(symbol)}"
        defs.append(
            f'<image id="{safe}" x="0" y="0" width="{square_size:g}" height="{square_size:g}" '
            f'preserveAspectRatio="none" href="data:image/png;base64,{payload}"/>'
        )
    defs.append('</defs>')

    parts = ['<g class="twitch-piece-set">', ''.join(defs)]
    for square, piece in board.piece_map().items():
        file_index = square & 7
        rank_index = square >> 3
        x = (file_index if orientation else 7 - file_index) * square_size + board_offset
        y = (7 - rank_index if orientation else rank_index) * square_size + board_offset
        safe = f"tw_{ord(piece.symbol())}"
        parts.append(f'<use href="#{safe}" x="{x:.2f}" y="{y:.2f}"/>')

    parts.append('</g>')
    return ''.join(parts)

if __name__ == '__main__':
    import argparse
    from pathlib import Path
    parser = argparse.ArgumentParser(description='Export the bundled original SVG drawings.')
    parser.add_argument('--export-svg', required=True, metavar='DIRECTORY')
    destination = Path(parser.parse_args().export_svg)
    for key, drawing in SVG_PIECES.items():
        target = destination / (key + '.svg')
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(drawing, encoding='utf-8')
    print(f'Exported {len(SVG_PIECES)} SVG drawings.')
